import { gql, useQuery } from '@apollo/client';
import { useMutation } from '@apollo/client';
export const GET_NOTIFICATIONS = gql `
  query GetNotifications($filter: NotificationFilter!) {
    notifications(filter: $filter) {
      id
      advertiser {
        id
        name
        bpid
      }
      advertiserId
      category
      code
      createdAt {
        ago
        at
      }
      level
      message
      module
      readStatus
      snoozeStatus
      link {
        type
        parameters
      }
    }
  }
`;
export const MARK_AS_READ = gql `
  mutation MarkAsRead($id: ID!) {
    markAsRead(id: $id)
  }
`;
export const MARK_AS_UNREAD = gql `
  mutation MarkAsUnread($id: ID!) {
    markAsUnread(id: $id)
  }
`;
export const SNOOZE_NOTIFICATION = gql `
  mutation Snooze($id: ID!) {
    snooze(id: $id)
  }
`;
export const UNSNOOZE_NOTIFICATION = gql `
  mutation UnSnooze($id: ID!) {
    unSnooze(id: $id)
  }
`;
export function useGetNotificationsQuery(filters) {
    return useQuery(GET_NOTIFICATIONS, {
        variables: {
            filter: filters,
        },
        fetchPolicy: 'no-cache',
    });
}
export function useMarkAsRead() {
    return useMutation(MARK_AS_READ);
}
export function useMarkAsUnread() {
    return useMutation(MARK_AS_UNREAD);
}
export function useSnoozeNotification() {
    return useMutation(SNOOZE_NOTIFICATION);
}
export function useUnSnoozeNotification() {
    return useMutation(UNSNOOZE_NOTIFICATION);
}
